import { styled, View } from '@tamagui/web';
import type { ReactElement } from 'react';
import { useMemo } from 'react';

import { ariaAndDataAttributes } from '../../helpers/ariaAndDataAttributes';
import { prependClassName } from '../../helpers/prependClassName';
import type { SpanAttributes } from '../../types/ElementAttributes';
import { Icon, type IconProps } from '../Icon';

export type ChevronProps = SpanAttributes & {
	size?: IconProps['size'];
	up?: boolean;
	right?: boolean;
	left?: boolean;
	down?: boolean;
};

// generated by scripts/generate-frame-values.mts from @rocket.chat/fuselage-tokens, do not edit

const chevronFrame = {
	render: 'span',
	display: 'inline-flex',
	flexDirection: 'row',
	alignItems: 'normal',
	flexShrink: 1,
	minWidth: 'auto',
	minHeight: 'auto',
	alignSelf: 'center',
} as const;

const chevronDirections = {
	up: {
		transform: 'rotate(-180deg)',
	},
	down: {
		transform: 'rotate(0deg)',
	},
	right: {
		transform: 'rotate(calc(-90deg * var(--rcx-dir)))',
	},
	left: {
		transform: 'rotate(calc(90deg * var(--rcx-dir)))',
	},
} as const;

// end of generated

const ChevronFrame = styled(View, {
	...chevronFrame,
	variants: {
		direction: chevronDirections,
	},
});

function Chevron(props: ChevronProps): ReactElement<ChevronProps> {
	const { up, right, down, left, size, className } = props;
	// The last one set wins, as the stylesheet's rules did
	const direction = (left && 'left') || (right && 'right') || (down && 'down') || (up && 'up') || undefined;
	const modifiers = [
		['up', up],
		['right', right],
		['down', down],
		['left', left],
	]
		.filter(([, on]) => on)
		.map(([name]) => `rcx-chevron--${name} `)
		.join('');
	const children = useMemo(() => <Icon name='chevron-down' size={size} />, [size]);

	return (
		<ChevronFrame
			direction={direction}
			className={prependClassName(className, `rcx-box rcx-box--full ${modifiers}rcx-chevron`)}
			render={<span {...ariaAndDataAttributes(props)} ref={props.ref} id={props.id} title={props.title} />}
		>
			{children}
		</ChevronFrame>
	);
}

export default Chevron;
